import {CHARACTER_METADATA_CATALOG} from './character-metadata-catalog.mjs';
import {applyCharacterSourceMetadata,sourceNumber} from './character-source-metadata.mjs';
import {sha256} from '../workshop/task-package.mjs';
const clone=structuredClone;
function consensus(rows){const data={};for(const group of new Set(rows.flatMap(row=>Object.keys(row.initialData)))){data[group]={};for(const key of new Set(rows.flatMap(row=>Object.keys(row.initialData[group]??{})))){const values=rows.map(row=>row.initialData[group]?.[key]).filter(value=>value!==undefined),canonical=value=>group==='信息'&&['_年龄','年龄','身高'].includes(key)?sourceNumber(value,{age:key!=='身高'})??String(value):JSON.stringify(value);if(values.length&&values.every(value=>canonical(value)===canonical(values[0])))data[group][key]=clone(values[0]);}}const appearances=rows.map(row=>row.appearance).filter(Boolean);return{name:rows[0].name,initialVariables:data,appearance:appearances.length&&appearances.every(value=>value===appearances[0])?appearances[0]:''};}
export async function characterMetadataSource(actor){const direct=CHARACTER_METADATA_CATALOG.records.filter(row=>row.actorIds.includes(actor.id));let rows=direct.length?direct:CHARACTER_METADATA_CATALOG.records.filter(row=>row.name===actor.name);if(!rows.length)return null;const entries=(actor.worldbook?.entries??[]).filter(entry=>entry.content&&(/persona|人设|角色设定/.test(entry.id+' '+entry.comment))),hashes=await Promise.all(entries.map(entry=>sha256(entry.content)));const exact=rows.filter(row=>hashes.includes(row.personaSha256));if(exact.length)rows=exact;return{role:consensus(rows),sources:rows.map(row=>row.source),ambiguous:rows.length>1,adultSchemaTrusted:exact.length>0||!entries.length&&direct.length===1};}
export async function migrateCharacterSourceMetadata(runtime){return runtime.personnelTransaction(async()=>{const reports=await runtime.store.readJson('migrations/character-ordinary-source-v1.json',{}),changed=[];for(const actor of await runtime.store.listObjects('character')){if(actor.id==='user')continue;const source=await characterMetadataSource(actor);if(!source)continue;const before=JSON.stringify(actor),report=await applyCharacterSourceMetadata(actor,source.role,{ordinaryOnly:!source.adultSchemaTrusted});reports[actor.id]={...report,sources:source.sources,ambiguous:source.ambiguous};if(before!==JSON.stringify(actor))changed.push(actor);}if(changed.length)await runtime._writeLocalObjects(changed,new Map([['migrations/character-ordinary-source-v1.json',reports]]));return{changed:changed.length,reports};});}
